lot = BlueRidge.Common.Util.extractQualifiedValues(self.view.custom.lot) or {}
lotId = lot.get("Id")
if not lotId:
	BlueRidge.Common.Notify.toast("No LOT", "No LOT loaded.", "warning")
	return
active = bool(lot.get("CrtActive"))
# Supervisor-only in BOTH directions (design D7): applying a Controlled Run
# Tag forces the 200% downstream inspection prompt, releasing one drops that
# obligation - neither transition is an operator decision. Per D6 this acts on
# THIS LOT only: no bulk clear, no clear-with-descendants.
# requireElevation stashes the intent and opens the ElevationModal;
# Session.dispatchElevatedAction replays it as the crtToggleRequested page
# message, whose handler calls straight back into this method.
if not BlueRidge.Common.Session.isElevated(self.session):
	if active:
		label = "Release the Controlled Run Tag"
	else:
		label = "Apply a Controlled Run Tag"
	BlueRidge.Common.Session.requireElevation(self.session, "CrtToggle", label, {})
	return
appUserId = self.session.custom.appUserId
termId = None
try:
	termId = self.session.custom.terminal.terminalLocationId
except:
	termId = None
if active:
	result = BlueRidge.Lots.Lot.clearCrt(lotId, appUserId, termId)
	BlueRidge.Common.Ui.notifyResult(result, "CRT released")
else:
	result = BlueRidge.Lots.Lot.setCrt(lotId, appUserId, termId)
	BlueRidge.Common.Ui.notifyResult(result, "CRT applied")
if result and result.get("Status"):
	self.load()
